(()=>{
const utf8=s=>{let a=[];for(const ch of s){let c=ch.codePointAt(0);if(c<128)a.push(c);else if(c<2048)a.push(192|(c>>6),128|(c&63));else if(c<65536)a.push(224|(c>>12),128|((c>>6)&63),128|(c&63));else a.push(240|(c>>18),128|((c>>12)&63),128|((c>>6)&63),128|(c&63));}return a;};
const prep=a=>{a=a.slice();let len=a.length*8;a.push(128);while(a.length%64!==56)a.push(0);for(let j=7;j>=0;j--)a.push(j>=4?Math.floor(len/2**(j*8))&255:(len>>>j*8)&255);return a;};
const hex=ws=>ws.map(v=>(v>>>0).toString(16).padStart(8,"0")).join("");
const sha256=input=>{let a=prep(typeof input==="string"?utf8(input):input),H=[0x6a09e667,0xbb67ae85,0x3c6ef372,0xa54ff53a,0x510e527f,0x9b05688c,0x1f83d9ab,0x5be0cd19],K=[0x428a2f98,0x71374491,0xb5c0fbcf,0xe9b5dba5,0x3956c25b,0x59f111f1,0x923f82a4,0xab1c5ed5,0xd807aa98,0x12835b01,0x243185be,0x550c7dc3,0x72be5d74,0x80deb1fe,0x9bdc06a7,0xc19bf174,0xe49b69c1,0xefbe4786,0x0fc19dc6,0x240ca1cc,0x2de92c6f,0x4a7484aa,0x5cb0a9dc,0x76f988da,0x983e5152,0xa831c66d,0xb00327c8,0xbf597fc7,0xc6e00bf3,0xd5a79147,0x06ca6351,0x14292967,0x27b70a85,0x2e1b2138,0x4d2c6dfc,0x53380d13,0x650a7354,0x766a0abb,0x81c2c92e,0x92722c85,0xa2bfe8a1,0xa81a664b,0xc24b8b70,0xc76c51a3,0xd192e819,0xd6990624,0xf40e3585,0x106aa070,0x19a4c116,0x1e376c08,0x2748774c,0x34b0bcb5,0x391c0cb3,0x4ed8aa4a,0x5b9cca4f,0x682e6ff3,0x748f82ee,0x78a5636f,0x84c87814,0x8cc70208,0x90befffa,0xa4506ceb,0xbef9a3f7,0xc67178f2],ro=(x,n)=>(x>>>n)|(x<<(32-n));for(let o=0;o<a.length;o+=64){let w=[];for(let i=0;i<16;i++)w[i]=(a[o+4*i]<<24)|(a[o+4*i+1]<<16)|(a[o+4*i+2]<<8)|a[o+4*i+3];for(let i=16;i<64;i++){let x=w[i-15],y=w[i-2];w[i]=(w[i-16]+(ro(x,7)^ro(x,18)^(x>>>3))+w[i-7]+(ro(y,17)^ro(y,19)^(y>>>10)))|0;}let [b,c,d,e,f,g,h,j]=H;for(let i=0;i<64;i++){let t1=(j+(ro(f,6)^ro(f,11)^ro(f,25))+((f&g)^((~f)&h))+K[i]+w[i])|0,t2=((ro(b,2)^ro(b,13)^ro(b,22))+((b&c)^(b&d)^(c&d)))|0;j=h;h=g;g=f;f=(e+t1)|0;e=d;d=c;c=b;b=(t1+t2)|0;}H=[b,c,d,e,f,g,h,j].map((v,i)=>(H[i]+v)|0);}return hex(H);};
const sha1=input=>{let a=prep(typeof input==="string"?utf8(input):input),H=[0x67452301,0xefcdab89,0x98badcfe,0x10325476,0xc3d2e1f0],rol=(x,n)=>(x<<n)|(x>>>(32-n));for(let o=0;o<a.length;o+=64){let w=[];for(let i=0;i<16;i++)w[i]=(a[o+4*i]<<24)|(a[o+4*i+1]<<16)|(a[o+4*i+2]<<8)|a[o+4*i+3];for(let i=16;i<80;i++)w[i]=rol(w[i-3]^w[i-8]^w[i-14]^w[i-16],1);let[b,c,d,e,f]=H;for(let i=0;i<80;i++){let F=i<20?(c&d)|((~c)&e):i<40?c^d^e:i<60?(c&d)|(c&e)|(d&e):c^d^e;let k=i<20?0x5a827999:i<40?0x6ed9eba1:i<60?0x8f1bbcdc:0xca62c1d6;let t=(rol(b,5)+F+f+k+w[i])|0;f=e;e=d;d=rol(c,30);c=b;b=t;}H=[b,c,d,e,f].map((v,i)=>(H[i]+v)|0);}return hex(H);};
return {utf8,sha256,sha1,blob:s=>sha1(utf8("blob "+utf8(s).length+"\0").concat(utf8(s)))};
})()
